using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using RaceDay.Api.Data; using RaceDay.Api.Models;
namespace RaceDay.Api.Controllers;
[Route("api/events")]
public class EventsController(RaceDayContext db) : ApiControllerBase
{
 public record EventDto(string Name,string? Description,DateTime Date,string Location,decimal Distance,string EventType);
 public record CategoryDto(string Name,string Type,int? MinimumAge,int? MaximumAge,decimal? Distance,string? Gender,string? Description,int? TeamSize);
 [HttpGet] public async Task<IActionResult> List(){if(RequireLogin() is IActionResult e)return e;return Ok(await db.Events.AsNoTracking().Select(x=>new{x.EventID,Name=x.EventName,Description=x.EventDescription,Date=x.EventDate,StartLocation=x.StartLocation,EndLocation=x.EndLocation,Distance=(decimal?)null,x.EventType,x.Status}).ToListAsync());}
 [HttpGet("{id:int}")] public async Task<IActionResult> Get(int id){if(RequireLogin() is IActionResult e)return e;var x=await db.Events.FindAsync(id);return x is null?NotFound():Ok(x);}
 [HttpPost] public async Task<IActionResult> Create(EventDto d){if(RequireRole("Organiser") is IActionResult e)return e;if(!Valid(d))return BadRequest("Valid name, location, positive distance and Run/Walk/Cycle type are required.");var x=new Event{EventName=d.Name,EventDescription=d.Description,EventDate=d.Date,StartLocation=d.Location,EndLocation=d.Location,EventType=TitleType(d.EventType),Status="Published"};db.Events.Add(x);await db.SaveChangesAsync();db.EventOrganisers.Add(new EventOrganiser{UserID=CurrentUserId!.Value,EventID=x.EventID,RoleInEvent="Main"});await db.SaveChangesAsync();return CreatedAtAction(nameof(Get),new{id=x.EventID},x);}
 [HttpPut("{id:int}")] public async Task<IActionResult> Update(int id,EventDto d){if(RequireRole("Organiser") is IActionResult e)return e;var x=await db.Events.FindAsync(id);if(x is null)return NotFound();if(!await Owns(id))return Forbid();if(!Valid(d))return BadRequest("Invalid event details.");x.EventName=d.Name;x.EventDescription=d.Description;x.EventDate=d.Date;x.StartLocation=d.Location;x.EndLocation=d.Location;x.EventType=TitleType(d.EventType);await db.SaveChangesAsync();return Ok(x);}
 [HttpDelete("{id:int}")] public async Task<IActionResult> Delete(int id){if(RequireRole("Organiser") is IActionResult e)return e;var x=await db.Events.FindAsync(id);if(x is null)return NotFound();if(!await Owns(id))return Forbid();if(await db.Registrations.AnyAsync(r=>r.EventID==id))return Conflict("Cannot delete an event with registrations; cancel it instead.");db.Events.Remove(x);await db.SaveChangesAsync();return NoContent();}
 [HttpGet("{eventId:int}/categories")] public async Task<IActionResult> Categories(int eventId){if(RequireLogin() is IActionResult e)return e;if(!await db.Events.AnyAsync(x=>x.EventID==eventId))return NotFound();return Ok(await db.Categories.Where(x=>x.EventID==eventId).ToListAsync());}
 [HttpPost("{eventId:int}/categories")] public async Task<IActionResult> CreateCategory(int eventId,CategoryDto d){if(RequireRole("Organiser") is IActionResult e)return e;if(!await db.Events.AnyAsync(x=>x.EventID==eventId))return NotFound();if(!await Owns(eventId))return Forbid();if(string.IsNullOrWhiteSpace(d.Name)||string.IsNullOrWhiteSpace(d.Type)||(d.MinimumAge.HasValue&&d.MaximumAge.HasValue&&d.MinimumAge>d.MaximumAge)||d.Distance<=0)return BadRequest("Invalid category.");var c=new Category{EventID=eventId,CategoryName=d.Name,CategoryType=d.Type,MinAge=d.MinimumAge,MaxAge=d.MaximumAge,Distance=d.Distance,Gender=d.Gender??"Open",Description=d.Description,TeamSize=d.TeamSize};db.Categories.Add(c);await db.SaveChangesAsync();return Created($"/api/events/{eventId}/categories",c);}
 [HttpPut("{eventId:int}/categories/{categoryId:int}")] public async Task<IActionResult> UpdateCategory(int eventId,int categoryId,CategoryDto d){if(RequireRole("Organiser") is IActionResult e)return e;if(!await Owns(eventId))return Forbid();var c=await db.Categories.SingleOrDefaultAsync(x=>x.EventID==eventId&&x.CategoryID==categoryId);if(c is null)return NotFound();if(string.IsNullOrWhiteSpace(d.Name)||string.IsNullOrWhiteSpace(d.Type))return BadRequest();c.CategoryName=d.Name;c.CategoryType=d.Type;c.MinAge=d.MinimumAge;c.MaxAge=d.MaximumAge;c.Distance=d.Distance;c.Gender=d.Gender??"Open";c.Description=d.Description;c.TeamSize=d.TeamSize;await db.SaveChangesAsync();return Ok(c);}
 [HttpDelete("{eventId:int}/categories/{categoryId:int}")] public async Task<IActionResult> DeleteCategory(int eventId,int categoryId){if(RequireRole("Organiser") is IActionResult e)return e;if(!await Owns(eventId))return Forbid();var c=await db.Categories.SingleOrDefaultAsync(x=>x.EventID==eventId&&x.CategoryID==categoryId);if(c is null)return NotFound();if(await db.Registrations.AnyAsync(x=>x.CategoryID==categoryId))return Conflict("Category has registrations.");db.Categories.Remove(c);await db.SaveChangesAsync();return NoContent();}
 private Task<bool> Owns(int eventId)=>db.EventOrganisers.AnyAsync(x=>x.EventID==eventId&&x.UserID==CurrentUserId);
 private static bool Valid(EventDto d)=>!string.IsNullOrWhiteSpace(d.Name)&&!string.IsNullOrWhiteSpace(d.Location)&&d.Distance>0&&!string.IsNullOrWhiteSpace(d.EventType)&&new[]{"run","walk","cycle"}.Contains(d.EventType.ToLower()); private static string TitleType(string x)=>char.ToUpper(x[0])+x[1..].ToLower();
}
